inline void enc_request_entry(std::string& out, const RequestEntry& v, int depth) {
    if (const auto n = static_cast<std::uint64_t>(v.preferred_model.size()); n > 256ULL) throw Refusal("bad_value",0);
    if (const auto n = static_cast<std::uint64_t>(v.unavailable_hosts.size()); n > 64ULL) throw Refusal("bad_value",0);
    for (const auto& oaElement : v.unavailable_hosts) {
    if (const auto n = static_cast<std::uint64_t>(oaElement.size()); n < 1ULL || n > 4096ULL) throw Refusal("bad_value",0);
    }
    if (const auto n = static_cast<std::uint64_t>(v.selection.size()); n > 64ULL) throw Refusal("bad_value",0);
    for (std::size_t i = 0; i < v.selection.size(); ++i) { const auto c = static_cast<unsigned char>(v.selection[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < v.selection.size() && static_cast<unsigned char>(v.selection[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "entry");
    out += ": ";
    enc_audit_entry(out, v.entry, depth + 1);
    if (!v.preferred_model.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "preferred_model");
        out += ": ";
        esc(out, v.preferred_model);
    }
    if (!v.unavailable_hosts.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "unavailable_hosts");
        out += ": ";
        strs(out, v.unavailable_hosts, depth + 1);
    }
    if (!v.selection.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "selection");
        out += ": ";
        esc(out, v.selection);
    }
    if (v.placement.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "placement");
        out += ": ";
        esc(out, *v.placement);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

