inline void enc_program_budget(std::string& out, const ProgramBudget& v, int depth) {
    if (v.tokens_per_day < 0LL || v.tokens_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    if (v.micros_per_day < 0LL || v.micros_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    if (v.requests_per_day < 0LL || v.requests_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    if (v.images_per_day < 0LL || v.images_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    if (v.audio_seconds_per_day < 0LL || v.audio_seconds_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    if (v.characters_per_day < 0LL || v.characters_per_day > 9223372036854775807LL) throw Refusal("bad_value",0);
    out += '{';
    bool first = true;
    if (v.tokens_per_day != 0) {
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "tokens_per_day");
        out += ": ";
        num(out, v.tokens_per_day);
    }
    if (v.micros_per_day != 0) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "micros_per_day");
        out += ": ";
        num(out, v.micros_per_day);
    }
    if (v.requests_per_day != 0) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "requests_per_day");
        out += ": ";
        num(out, v.requests_per_day);
    }
    if (v.images_per_day != 0) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "images_per_day");
        out += ": ";
        num(out, v.images_per_day);
    }
    if (v.audio_seconds_per_day != 0) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "audio_seconds_per_day");
        out += ": ";
        num(out, v.audio_seconds_per_day);
    }
    if (v.characters_per_day != 0) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "characters_per_day");
        out += ": ";
        num(out, v.characters_per_day);
    }
    if (!first) { out += '\n'; pad(out, depth); }
    out += '}';
}

